    18→
    19→// AuthMethod represents the SSH authentication method to use.
    20→type AuthMethod string
    21→
    22→const (
    23→	// AuthMethodPrivateKey uses SSH private key authentication (default).
    24→	AuthMethodPrivateKey AuthMethod = "private_key"
    25→	// AuthMethodPassword uses password authentication.
    26→	AuthMethodPassword AuthMethod = "password"
    27→	// AuthMethodCertificate uses SSH certificate authentication.
    28→	AuthMethodCertificate AuthMethod = "certificate"
    29→)
    30→
    31→// Config holds SSH connection configuration.
    32→type Config struct {
    33→	Host string
    34→	Port int
    35→	User string
    36→
    37→	// Authentication method (defaults to private_key if not specified).
    38→	AuthMethod AuthMethod
    39→
    40→	// Private key authentication.
    41→	PrivateKey string // Key content (PEM encoded)
    42→	KeyPath    string // Path to key file
    43→
    44→	// Password authentication.
    45→	Password string
    46→
    47→	// Certificate authentication.
    48→	Certificate     string // Certificate content
    49→	CertificatePath string // Path to certificate file
    50→
    51→	// Connection options.
    52→	Timeout time.Duration // Connection timeout (default 30s)
    53→
    54→	// Host key verification.
    55→	KnownHostsFile        string // Path to known_hosts file
    56→	InsecureIgnoreHostKey bool   // Skip host key verification (DANGEROUS)
    57→
    58→	// Bastion/Jump host configuration for multihop SSH.
    59→	BastionHost     string
    60→	BastionPort     int
    61→	BastionUser     string
    62→	BastionKey      string // Private key content for bastion
    63→	BastionKeyPath  string // Path to private key for bastion
    64→	BastionPassword string // Password for bastion (if using password auth)
    65→}
    66→
    67→// ClientInterface defines the interface for SSH/SFTP operations.
    68→type ClientInterface interface {
    69→	Close() error
    70→	UploadFile(ctx context.Context, localPath, remotePath string) error
    71→	UploadContent(ctx context.Context, content []byte, remotePath string) error
    72→	GetFileHash(ctx context.Context, remotePath string) (string, error)
    73→	SetFileAttributes(ctx context.Context, remotePath, owner, group, mode string) error
    74→	DeleteFile(ctx context.Context, remotePath string) error
    75→	FileExists(ctx context.Context, remotePath string) (bool, error)
    76→	GetFileInfo(ctx context.Context, remotePath string) (os.FileInfo, error)
    77→	ReadFileContent(ctx context.Context, remotePath string, maxBytes int64) ([]byte, error)
    78→	RunCommand(ctx context.Context, command string) (stdout string, stderr string, err error)
    79→}
    80→
    81→// Client wraps gosftp and SSH connections for file operations.
    82→type Client struct {
    83→	gosftpClient *gosftp.Client
    84→	sshClient    *ssh.Client
    85→	config       Config
    86→}
    87→
    88→var _ ClientInterface = (*Client)(nil)
    89→
    90→// NewClient creates a new SSH/SFTP client using gosftp.
    91→func NewClient(config Config) (*Client, error) {
    92→	gosftpConfig := gosftp.Config{
    93→		Host:                  config.Host,
    94→		Port:                  config.Port,
    95→		User:                  config.User,
    96→		AuthMethod:            gosftp.AuthMethod(config.AuthMethod),
    97→		PrivateKey:            config.PrivateKey,
    98→		KeyPath:               config.KeyPath,
    99→		Password:              config.Password,
   100→		Certificate:           config.Certificate,
   101→		CertificatePath:       config.CertificatePath,
   102→		Timeout:               config.Timeout,
   103→		KnownHostsFile:        config.KnownHostsFile,
   104→		InsecureIgnoreHostKey: config.InsecureIgnoreHostKey,
   105→		BastionHost:           config.BastionHost,
   106→		BastionPort:           config.BastionPort,
   107→		BastionUser:           config.BastionUser,
   108→		BastionKey:            config.BastionKey,
   109→		BastionKeyPath:        config.BastionKeyPath,
   110→		BastionPassword:       config.BastionPassword,
   111→	}
   112→
   113→	gosftpClient, err := gosftp.NewClient(gosftpConfig)
   114→	if err != nil {
   115→		return nil, fmt.Errorf("failed to create gosftp client: %w", err)
   116→	}
   117→
   118→	// For RunCommand support, we need the underlying SSH client
   119→	// We'll keep a separate SSH client for command execution
   120→	var sshClient *ssh.Client
   121→
   122→	return &Client{
   123→		gosftpClient: gosftpClient,
   124→		sshClient:    sshClient,
   125→		config:       config,
   126→	}, nil
   127→}
