   269→func buildAuthMethods(config Config) ([]ssh.AuthMethod, error) {
   270→	var authMethods []ssh.AuthMethod
   271→
   272→	authMethod := config.AuthMethod
   273→	if authMethod == "" {
   274→		authMethod = inferAuthMethod(config)
   275→	}
   276→
   277→	switch authMethod {
   278→	case AuthMethodPassword:
   279→		if config.Password == "" {
   280→			return nil, fmt.Errorf("password authentication requires password to be set")
   281→		}
   282→		authMethods = append(authMethods, ssh.Password(config.Password))
   283→
   284→	case AuthMethodCertificate:
   285→		certAuth, err := buildCertificateAuth(config)
   286→		if err != nil {
   287→			return nil, fmt.Errorf("certificate authentication failed: %w", err)
   288→		}
   289→		authMethods = append(authMethods, certAuth)
   290→
   291→	case AuthMethodPrivateKey, "":
   292→		keyAuth, err := buildPrivateKeyAuth(config)
   293→		if err != nil {
   294→			return nil, err
   295→		}
   296→		authMethods = append(authMethods, keyAuth)
   297→	}
   298→
   299→	return authMethods, nil
   300→}
   301→
   302→func inferAuthMethod(config Config) AuthMethod {
   303→	if config.Password != "" {
   304→		return AuthMethodPassword
   305→	}
   306→	if config.Certificate != "" || config.CertificatePath != "" {
   307→		return AuthMethodCertificate
   308→	}
   309→	return AuthMethodPrivateKey
   310→}
   311→
   312→func buildPrivateKeyAuth(config Config) (ssh.AuthMethod, error) {
   313→	var keyData []byte
   314→	var err error
   315→
   316→	if config.PrivateKey != "" {
   317→		keyData = []byte(config.PrivateKey)
   318→	} else if config.KeyPath != "" {
   319→		keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   320→		if err != nil {
   321→			return nil, fmt.Errorf("failed to read SSH key file: %w", err)
   322→		}
   323→	} else {
   324→		return nil, fmt.Errorf("no SSH private key provided (set private_key or key_path)")
   325→	}
   326→
   327→	signer, err := ssh.ParsePrivateKey(keyData)
   328→	if err != nil {
   329→		return nil, fmt.Errorf("failed to parse SSH private key: %w", err)
   330→	}
   331→
   332→	return ssh.PublicKeys(signer), nil
   333→}
   334→
   335→func buildCertificateAuth(config Config) (ssh.AuthMethod, error) {
   336→	var keyData []byte
   337→	var err error
   338→
   339→	if config.PrivateKey != "" {
   340→		keyData = []byte(config.PrivateKey)
   341→	} else if config.KeyPath != "" {
   342→		keyData, err = os.ReadFile(ExpandPath(config.KeyPath))
   343→		if err != nil {
   344→			return nil, fmt.Errorf("failed to read private key file: %w", err)
   345→		}
   346→	} else {
   347→		return nil, fmt.Errorf("certificate auth requires private key (set private_key or key_path)")
   348→	}
   349→
   350→	signer, err := ssh.ParsePrivateKey(keyData)
   351→	if err != nil {
   352→		return nil, fmt.Errorf("failed to parse private key: %w", err)
   353→	}
   354→
   355→	var certData []byte
   356→	if config.Certificate != "" {
   357→		certData = []byte(config.Certificate)
   358→	} else if config.CertificatePath != "" {
   359→		certData, err = os.ReadFile(ExpandPath(config.CertificatePath))
   360→		if err != nil {
   361→			return nil, fmt.Errorf("failed to read certificate file: %w", err)
   362→		}
   363→	} else {
   364→		return nil, fmt.Errorf("certificate auth requires certificate (set certificate or certificate_path)")
   365→	}
   366→
   367→	pubKey, _, _, _, err := ssh.ParseAuthorizedKey(certData)
   368→	if err != nil {
   369→		return nil, fmt.Errorf("failed to parse certificate: %w", err)
   370→	}
   371→
   372→	cert, ok := pubKey.(*ssh.Certificate)
   373→	if !ok {
   374→		return nil, fmt.Errorf("provided file is not an SSH certificate")
   375→	}
   376→
   377→	certSigner, err := ssh.NewCertSigner(cert, signer)
   378→	if err != nil {
   379→		return nil, fmt.Errorf("failed to create certificate signer: %w", err)
   380→	}
   381→
   382→	return ssh.PublicKeys(certSigner), nil
   383→}
