   385→// Close closes the gosftp client and SSH connections.
   386→func (c *Client) Close() error {
   387→	if c.gosftpClient != nil {
   388→		return c.gosftpClient.Close()
   389→	}
   390→	return nil
   391→}
   392→
   393→// UploadFile uploads a local file to the remote host.
   394→func (c *Client) UploadFile(ctx context.Context, localPath, remotePath string) error {
   395→	return c.gosftpClient.UploadFile(ctx, localPath, remotePath)
   396→}
   397→
   398→// UploadContent uploads content directly to the remote host.
   399→// Since gosftp doesn't have a direct UploadContent method, we write to a temp file first.
   400→func (c *Client) UploadContent(ctx context.Context, content []byte, remotePath string) error {
   401→	// Write content to a temporary file
   402→	tmpFile, err := os.CreateTemp("", "upload-*")
   403→	if err != nil {
   404→		return fmt.Errorf("failed to create temporary file: %w", err)
   405→	}
   406→	defer os.Remove(tmpFile.Name())
   407→
   408→	if _, err := tmpFile.Write(content); err != nil {
   409→		tmpFile.Close()
   410→		return fmt.Errorf("failed to write to temporary file: %w", err)
   411→	}
   412→	tmpFile.Close()
   413→
   414→	// Upload the temporary file
   415→	return c.gosftpClient.UploadFile(ctx, tmpFile.Name(), remotePath)
   416→}
   417→
   418→// GetFileHash returns the SHA256 hash of a remote file.
   419→func (c *Client) GetFileHash(ctx context.Context, remotePath string) (string, error) {
   420→	return c.gosftpClient.GetFileHash(ctx, remotePath)
   421→}
   422→
   423→// SetFileAttributes sets ownership and permissions on a remote file.
   424→func (c *Client) SetFileAttributes(ctx context.Context, remotePath, owner, group, mode string) error {
   425→	if err := validateOwnerGroup(owner, "owner"); err != nil {
   426→		return err
   427→	}
   428→	if err := validateOwnerGroup(group, "group"); err != nil {
   429→		return err
   430→	}
   431→	if err := ValidateMode(mode); err != nil {
   432→		return err
   433→	}
   434→
   435→	return c.gosftpClient.SetFileAttributes(ctx, remotePath, owner, group, mode)
   436→}
   437→
   438→// DeleteFile removes a file from the remote host.
   439→func (c *Client) DeleteFile(ctx context.Context, remotePath string) error {
   440→	return c.gosftpClient.DeleteFile(ctx, remotePath)
   441→}
   442→
   443→// FileExists checks if a file exists on the remote host.
   444→func (c *Client) FileExists(ctx context.Context, remotePath string) (bool, error) {
   445→	return c.gosftpClient.FileExists(ctx, remotePath)
   446→}
   447→
   448→// GetFileInfo returns information about a remote file.
   449→func (c *Client) GetFileInfo(ctx context.Context, remotePath string) (os.FileInfo, error) {
   450→	return c.gosftpClient.GetFileInfo(ctx, remotePath)
   451→}
   452→
   453→// ReadFileContent reads the content of a remote file.
   454→func (c *Client) ReadFileContent(ctx context.Context, remotePath string, maxBytes int64) ([]byte, error) {
   455→	return c.gosftpClient.ReadFileContent(ctx, remotePath, maxBytes)
   456→}
   457→
   458→// RunCommand executes a command on the remote host.
   459→// Returns stdout, stderr, and any error.
   460→func (c *Client) RunCommand(ctx context.Context, command string) (string, string, error) {
   461→	// For now, we need to create an SSH client for command execution
   462→	// since gosftp focuses on SFTP operations
   463→	authMethods, err := buildAuthMethods(c.config)
   464→	if err != nil {
   465→		return "", "", err
   466→	}
   467→
   468→	hostKeyCallback, err := buildHostKeyCallback(c.config)
   469→	if err != nil {
   470→		return "", "", err
   471→	}
   472→
   473→	timeout := c.config.Timeout
   474→	if timeout == 0 {
   475→		timeout = 30 * time.Second
   476→	}
   477→
   478→	port := c.config.Port
   479→	if port == 0 {
   480→		port = 22
   481→	}
   482→
   483→	sshConfig := &ssh.ClientConfig{
   484→		User:            c.config.User,
   485→		Auth:            authMethods,
   486→		HostKeyCallback: hostKeyCallback,
   487→		Timeout:         timeout,
   488→	}
   489→
   490→	targetAddr := fmt.Sprintf("%s:%d", c.config.Host, port)
   491→
   492→	var sshClient *ssh.Client
   493→	var bastionClient *ssh.Client
   494→
   495→	if c.config.BastionHost != "" {
   496→		bastionClient, err = connectToBastion(c.config, timeout)
   497→		if err != nil {
   498→			return "", "", fmt.Errorf("failed to connect to bastion host: %w", err)
   499→		}
   500→		defer bastionClient.Close()
   501→
   502→		conn, err := bastionClient.Dial("tcp", targetAddr)
   503→		if err != nil {
   504→			return "", "", fmt.Errorf("failed to dial target through bastion: %w", err)
   505→		}
   506→
   507→		ncc, chans, reqs, err := ssh.NewClientConn(conn, targetAddr, sshConfig)
   508→		if err != nil {
   509→			conn.Close()
   510→			return "", "", fmt.Errorf("failed to create SSH connection through bastion: %w", err)
   511→		}
   512→
   513→		sshClient = ssh.NewClient(ncc, chans, reqs)
   514→	} else {
   515→		sshClient, err = ssh.Dial("tcp", targetAddr, sshConfig)
   516→		if err != nil {
   517→			return "", "", fmt.Errorf("failed to connect to %s: %w", targetAddr, err)
   518→		}
   519→	}
   520→	defer sshClient.Close()
   521→
   522→	session, err := sshClient.NewSession()
   523→	if err != nil {
   524→		return "", "", fmt.Errorf("failed to create SSH session: %w", err)
   525→	}
   526→	defer session.Close()
   527→
   528→	var stdout, stderr bytes.Buffer
   529→	session.Stdout = &stdout
   530→	session.Stderr = &stderr
   531→
   532→	err = session.Run(command)
   533→	return stdout.String(), stderr.String(), err
   534→}
